def sanitize(text: str, mode: str) -> str:
    toks = [t for t in re.findall(r"[a-z0-9]+", text.lower()) if t not in STOPWORDS]
    seen: list[str] = []
    for t in toks:
        if t not in seen:
            seen.append(t)
    return (" " if mode == "and" else " OR ").join(seen)
